def can_unlock_all_doors(n, m, room_status, switches):
    from collections import defaultdict

    # This will store which switches control each room
    room_to_switches = defaultdict(list)
    for i in range(m):
        switch = switches[i]
        for room in switch[1:]:
            room_to_switches[room].append(i)

    # This will keep track of how many switches toggle each door to locked/unlocked
    locked_by_switches = [0] * n
    unlocked_by_switches = [0] * n

    # Initial state
    for i in range(n):
        if room_status[i] == 0:
            locked_by_switches[i] += 1
        else:
            unlocked_by_switches[i] += 1

    # Process each switch
    for switch_index in range(m):
        toggle_count = 0
        for room in switches[switch_index][1:]:
            if room_status[room - 1] == 0:
                # If the door is locked, toggling this switch will unlock it
                toggle_count += 1

        # For each switch, it toggles two doors
        if toggle_count == 1:
            # Toggling this switch will unlock one door and lock the other one
            for room in switches[switch_index][1:]:
                if room_status[room - 1] == 0:
                    unlocked_by_switches[room - 1] += 1
                    locked_by_switches[room - 1] -= 1
                else:
                    unlocked_by_switches[room - 1] -= 1
                    locked_by_switches[room - 1] += 1
        elif toggle_count == 2:
            # Toggling this switch will lock both doors
            for room in switches[switch_index][1:]:
                unlocked_by_switches[room - 1] -= 1
                locked_by_switches[room - 1] += 1

    # Check if all doors are unlocked
    for i in range(n):
        if locked_by_switches[i] > 0:
            return "NO"
    return "YES"

