        for room in data[1:]:
            switches[room].append(i)

    graph = defaultdict(list)
    for i in range(1, n+1):
        if len(switches[i]) != 2:
            print("NO")
            return
        graph[switches[i][0]].append(switches[i][1])
        graph[switches[i][1]].append(switches[i][0])

    visited = set()
    def dfs(node, target):
        visited.add(node)
        if node == target:
            return True
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor, target):
                    return True
        return False

    for i in range(1, m+1):
        if i not in visited:
            if not dfs(i, i):
                print("NO")
                return

    print("YES")

